-- Lanes + sources. A funnel can have several sources (a Drive folder of ready
-- videos, a Google Sheet, or generated by the app); each instance comes from
-- exactly one of them. The ready-video lane also gains a transcript gate: a
-- transcribed video waits in 'transcript_review' until the operator approves
-- it, and only then can the paid copy + thumbnail step run. Additive only.

CREATE TABLE IF NOT EXISTS funnel_sources (
  id          bigserial PRIMARY KEY,
  tenant_id   text NOT NULL DEFAULT 'default' REFERENCES tenants(id),
  funnel_id   bigint NOT NULL REFERENCES funnels(id) ON DELETE CASCADE,
  type        text NOT NULL,                 -- drive_folder | sheet | generated
  ref         text NOT NULL DEFAULT '',      -- Drive folder id / sheet id / ''
  label       text NOT NULL DEFAULT '',
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (funnel_id, type, ref)
);

CREATE INDEX IF NOT EXISTS funnel_sources_funnel_idx ON funnel_sources (funnel_id);

-- The one source an instance came from.
--   source_type: drive_folder | drive_pick | sheet | generated (null = legacy)
--   source_id:   funnel_sources.id when the source is saved on the funnel
--   source_ref:  the item inside the source (the Drive file id of the video)
ALTER TABLE instances ADD COLUMN IF NOT EXISTS source_type text;
ALTER TABLE instances ADD COLUMN IF NOT EXISTS source_id   bigint REFERENCES funnel_sources(id) ON DELETE SET NULL;
ALTER TABLE instances ADD COLUMN IF NOT EXISTS source_ref  text;

CREATE INDEX IF NOT EXISTS instances_source_ref_idx ON instances (funnel_id, source_ref);

-- Hand-stepped runs are the generated lane.
UPDATE instances SET source_type = 'generated' WHERE source_type IS NULL AND status = 'manual';

-- Existing ready-video AI drafts: their video is the stitch step's Drive file.
UPDATE instances i
   SET source_type = 'drive_folder',
       source_ref = (SELECT s->'artifacts'->'video'->>'driveId'
                       FROM jsonb_array_elements(i.steps) s
                      WHERE s->>'key' = 'stitch' LIMIT 1)
 WHERE i.source_type IS NULL AND i.status = 'draft';
